// ─────────────────────────────────────────────────────────────
// All data is now in $json thanks to the Merge node:
//   statusCode, body  ← from the Discord API response
//   user_id, row_number ← from the original loop item
// No pairedItem lookup needed.
// ─────────────────────────────────────────────────────────────

const statusCode   = $json.statusCode;
const responseBody = String($json.body ?? '');
const userId       = $json.user_id;
const rowNumber    = $json.row_number;
const timestamp    = new Date().toISOString();

let status, errorMsg;

if (statusCode === 204 || statusCode === 200) {
  status   = 'done';
  errorMsg = '';

} else if (statusCode === 404) {
  status   = 'not_in_server';
  errorMsg = 'User not found in server — they may have left (404)';

} else if (statusCode === 429) {
  status   = 'rate_limited';
  errorMsg = `Discord rate limited the request (429): ${responseBody.substring(0, 100)}`;

} else if (statusCode === 403) {
  status   = 'failed';
  errorMsg = 'Bot lacks MANAGE_ROLES or target role is above bot in hierarchy (403)';

} else if (statusCode == null) {
  status   = 'failed';
  errorMsg = `Network error: ${String($json.error ?? 'unknown')}`;

} else {
  status   = 'failed';
  errorMsg = `HTTP ${statusCode}: ${responseBody.substring(0, 200)}`;
}

return [{
  json: { user_id: userId, row_number: rowNumber, status, timestamp, error: errorMsg }
}];
